contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We take an amount to send when calling play. Must model both correct and incorrect values.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // read observable state before the call
        uint pot_before = c.pot(); if (__ESBMC_reverted()) return;
        address bank_before = c.bank(); if (__ESBMC_reverted()) return;
        uint balance_c_before = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observable state after the call
        uint pot_after = c.pot(); if (__ESBMC_reverted()) return;
        uint balance_c_after = address(c).balance;

        // The general rule:
        // - If the call reverted then it must be because amount != TICKET_AMOUNT, so pot unchanged and contract balance unchanged.
        // - If the call succeeded then amount must equal TICKET_AMOUNT. After a successful call, either the pot increased by amount (no payout case),
        //   or the pot was reset to 0 (payout case). In the payout case the contract balance decreases by at least the fee amount,
        //   and in the no-payout case the contract balance increases by exactly amount.

        // We cannot reference internal constants TICKET_AMOUNT or FEE_AMOUNT directly here, so express relationships using observable values.
        // For the payout case detection: pot_after == 0
        bool payout_happened = (pot_after == 0);

        // For no-payout detection: pot increased by amount
        bool no_payout = (pot_after == pot_before + amount);

        // If reverted: pot and contract balance must be unchanged and amount was not the exact ticket price (i.e., must not have behaved like success)
        // If not reverted: amount must have been accepted (we encode that by requiring either payout_happened or no_payout holds and balance changed accordingly).

        // Build the assert condition expressing the above general rule using only observable values.
        assert(
            // Case A: reverted -> pot and contract balance unchanged
            (reverted && pot_after == pot_before && balance_c_after == balance_c_before)
            ||
            // Case B: succeeded -> either no_payout or payout_happened with consistent balance change
            (!reverted && (
                // no payout: pot increased by amount and contract balance increased by amount
                (no_payout && balance_c_after == balance_c_before + amount)
                ||
                // payout: pot reset to 0 and contract balance is less than or equal to balance before + amount (because payout transfers out)
                (payout_happened && balance_c_after <= balance_c_before + amount)
            ))
        );
    }

    receive() external payable { }
}

